}

public class Main {
    public static void main(String[] args) {
        Minuman es = new Minuman();
        es.nama = "Es Teh";
        es.harga = 5000;
        es.ml = 400;
        es.info();
        System.out.println("Isi: " + es.ml + " ml");
        Makanan seblak = new Makanan();
        seblak.nama = "Seblak";
        seblak.harga = 12000;
        seblak.pedas = true;
        seblak.info();
        System.out.println("Pedas: " + seblak.pedas);
        seblak.diskon(2000);
        seblak.info();
    }
}

class Produk {
    String nama;
    int harga;

    void diskon(int potongan) {
        harga -= potongan;
    }

    void info() {
        System.out.println(nama + " - " + harga);
    }
}

class Minuman extends Produk {
    int ml;
}

class Makanan extends Produk {
    boolean pedas;
}

